update public.games set subtitle = 'Modalidad Escuadras (Squads - Battle Royale)', badge = 'BATTLE ROYALE SQUADS', scoring_table = $json$[{"pos":"1ro (Booyah!)","pts":"12 pts"},{"pos":"2do","pts":"9 pts"},{"pos":"3ro","pts":"8 pts"},{"pos":"4to","pts":"7 pts"},{"pos":"5to","pts":"6 pts"},{"pos":"6to","pts":"5 pts"},{"pos":"7mo","pts":"4 pts"},{"pos":"8vo","pts":"3 pts"},{"pos":"9no","pts":"2 pts"},{"pos":"10mo a 12vo","pts":"1 pt"},{"pos":"Por Asesinato (Kill)","pts":"+1 pt / Kill"}]$json$::jsonb
  where key = 'ff' and subtitle = '';

-- Secciones del reglamento
insert into public.rules_sections (game_key, position, title, highlight, points)
select 'mlbb', r.position, r.title, r.highlight, r.points
from jsonb_to_recordset($json$[{"position":1,"title":"Formato del Torneo y Estructura","highlight":"Modo Torneo Draft Pick 5v5 · BO1 eliminatorias y BO3 semifinal/final","points":["Modo de Juego: Personalizada - Modo Torneo (Draft Pick 5v5).","Estructura de Brackets: Rondas eliminatorias y cuartos de final al Mejor de 1 (BO1). Semifinales y Gran Final al Mejor de 3 (BO3).","Dispositivos: Única y estrictamente dispositivos móviles (celulares o tablets). El uso de emuladores en PC está totalmente prohibido.","Condición de Victoria: La partida finaliza cuando el Nexo (Base) enemigo es destruido o mediante rendición oficial a través del sistema del juego."]},{"position":2,"title":"Inscripciones y Requisitos de Escuadra","highlight":"5 titulares obligatorios + hasta 2 suplentes · ID de jugador","points":["Estructura del Equipo: Cada escuadra debe registrar obligatoriamente a 5 jugadores titulares. Opcionalmente, se permite el registro de hasta 2 jugadores suplentes.","Identificación (IDs): Es obligatorio registrar el ID de jugador de todos los integrantes.","El Capitán: Será el único medio de comunicación oficial. Debe proveer su nombre real, número de WhatsApp y su institución (UNAP u otra).","Validación de Pagos (Yape): La inscripción será válida tras verificar el comprobante de pago. En caso de ganar, el pozo de premios será transferido única y exclusivamente a la cuenta del capitán."]},{"position":3,"title":"Gestión de Salas (Lobby) y Seguridad","highlight":"10 minutos de tolerancia · Expulsión a no registrados · W.O. estricto","points":["Creación de la Sala: El árbitro creará la sala e invitará a los dos capitanes. Los capitanes son responsables de invitar a su escuadra a sus respectivos lados (Equipo Rojo o Azul).","Tolerancia y Puntualidad: Se otorgarán exactamente 10 minutos de tolerancia para que ambos equipos completen su alineación de 5 jugadores. Pasado el tiempo, el equipo incompleto será descalificado por W.O.","Coincidencia de Nicknames: Solo podrán participar los jugadores cuyo Nickname e ID coincidan exactamente con la base de datos oficial. Jugadores no registrados serán expulsados."]},{"position":4,"title":"Reglas de Partida (Draft Pick y Pausas)","highlight":"Máximo 2 pausas por partida (máx. 3 min) · Regla de remake en draft","points":["Desconexiones en el Draft Pick: Si un jugador se desconecta del lobby antes de que ambos equipos bloqueen (baneen) a su primer héroe, la sala será reiniciada. Si la desconexión ocurre después del primer baneo, la fase de selección debe continuar y la partida se jugará obligatoriamente.","Sistema de Pausas: Cada escuadra tiene derecho a solicitar un máximo de 2 pausas por partida por motivos de conexión (lag).","Duración de Pausas: Ninguna pausa podrá exceder los 3 minutos.","Procedimiento: El capitán o jugador afectado debe solicitar la pausa escribiendo en el chat global (\"All\"). El árbitro será el único encargado de ejecutar la pausa en el sistema."]},{"position":5,"title":"Conducta y Sanciones (Tolerancia Cero)","highlight":"Prohibido cambios durante partida · Cero toxicidad o recall spam extremo","points":["Uso del Suplente: Solo pueden ingresar antes de que inicie la fase de Draft Pick. Prohibido realizar cambios de jugadores durante una partida en curso.","Filtración de Contraseñas: Compartir capturas, enlaces o el ID de la sala privada con personas ajenas resultará en descalificación automática del equipo sin derecho a reembolso.","Comportamiento Tóxico: El uso de insultos, \"recall spam\" malintencionado extremo o agresión verbal en chat global hacia árbitros o rivales resultará en Warning (Advertencia) o descalificación directa."]}]$json$::jsonb) as r(position smallint, title text, highlight text, points jsonb)
where not exists (select 1 from public.rules_sections where game_key = 'mlbb');

insert into public.rules_sections (game_key, position, title, highlight, points)
select 'ff', r.position, r.title, r.highlight, r.points
from jsonb_to_recordset($json$[{"position":1,"title":"Formato del Torneo y Mapas","highlight":"Battle Royale 4 jugadores · Bermuda, Purgatorio y Kalahari · Móviles únicamente","points":["Modo de Juego: Battle Royale (Escuadras / 4 jugadores).","Dispositivos: Única y estrictamente dispositivos móviles (celulares o tablets). El uso de emuladores en PC está totalmente prohibido y resultará en descalificación automática.","Mapas Oficiales: Bermuda, Purgatorio y Kalahari (o según rotación oficial indicada por la administración)."]},{"position":2,"title":"Inscripciones y Requisitos","highlight":"4 titulares obligatorios + 1 suplente opcional · Comunicación oficial por WhatsApp","points":["Estructura del Equipo: Cada escuadra debe registrar obligatoriamente a 4 jugadores titulares. Opcionalmente, se permite el registro de 1 jugador suplente.","El Capitán: Será el único medio de comunicación oficial entre administración y equipo. Debe proveer su nombre real, número de WhatsApp y su institución (UNAP u otra).","Validación de Pagos (Yape): La inscripción solo se considerará válida una vez que el pago haya sido verificado. En caso de ganar, el premio será transferido exclusivamente a la cuenta del capitán."]},{"position":3,"title":"Gestión de Salas (Lobby) y Seguridad","highlight":"Envío de ID 15 min antes · 10 min de tolerancia (mín. 3) · Slots asignados","points":["Comunicación de Credenciales: El ID y la contraseña de la sala privada se enviarán al grupo VIP de capitanes en WhatsApp 15 minutos antes del inicio de la partida.","Tolerancia y Puntualidad: Se darán exactamente 10 minutos de tolerancia para que los jugadores ingresen. Pasado este tiempo, la partida iniciará. Si un equipo está incompleto, deberá jugar con los integrantes presentes (mínimo 3).","Asignación de Slots: Cada equipo deberá ocupar la casilla (Slot) que la administración le asigne en el grupo de WhatsApp.","Coincidencia de Nicknames e IDs: El ingreso a las salas está reservado exclusivamente para los Nicknames e IDs registrados en la inscripción web. Jugadores no registrados serán expulsados de inmediato.","Uso del Suplente: Solo puede entrar a la sala si un titular presenta fallas técnicas antes del inicio. No se permiten cambios con la partida iniciada."]},{"position":4,"title":"Sistema Oficial de Puntuación","highlight":"Puntaje por posición final (Top) + 1 punto por asesinato (Kill)","points":["La clasificación de los equipos se determinará sumando los puntos por posición y los asesinatos confirmados en cada sala jugada.","Criterios de Desempate: En caso de empate en la tabla general, se resolverá por mayor cantidad de Booyahs obtenidos, luego por mayor número de kills totales y finalmente por mejor posición promedio."]},{"position":5,"title":"Conducta y Sanciones (Tolerancia Cero)","highlight":"Reporte de capturas en 10 min · Baneo permanente por hacks · No filtración de claves","points":["Reporte Obligatorio de Resultados: El capitán debe subir la captura de pantalla de resultados finales al canal oficial dentro de los 10 minutos posteriores a cada sala.","Filtración de Contraseñas: El capitán es responsable absoluto. Si el ID y clave son compartidos con terceros, la escuadra será descalificada en el acto sin derecho a reembolso.","Uso de Hacks o Alteraciones: El uso de programas de terceros, scripts, antenas o modificaciones al cliente resultará en baneo permanente de futuras ediciones.","Comportamiento Tóxico: Insultos o provocaciones extremas en el chat global de sala serán penalizados con deducción de puntos o expulsión directa."]}]$json$::jsonb) as r(position smallint, title text, highlight text, points jsonb)
where not exists (select 1 from public.rules_sections where game_key = 'ff');

-- Pasos de "Cómo participar"
insert into public.participation_steps (position, title, body, detail)
select r.position, r.title, r.body, r.detail
from jsonb_to_recordset($json$[{"position":1,"title":"ELIGE TU ARENA","body":"Mobile Legends o Free Fire. Elige tu disciplina y reúne a los jugadores que representarán a tu universidad.","detail":"DOS DISCIPLINAS / UN MISMO LEGADO"},{"position":2,"title":"REGISTRA TU ESCUADRA","body":"Completa los datos del capitán, tu institución y el ID de cada jugador. Añade a tus suplentes si tu equipo los necesita.","detail":"CAPITÁN + ROSTER + UNIVERSIDAD"},{"position":3,"title":"PREPARA TU INSCRIPCIÓN","body":"Revisa el reglamento de tu juego y adjunta el comprobante de pago por Yape para la revisión de la organización.","detail":"BASES OFICIALES / COMPROBANTE"}]$json$::jsonb) as r(position smallint, title text, body text, detail text)
where not exists (select 1 from public.participation_steps);
